SELECT 
  FROM oa_iam.identity
 WHERE tenant_id = #{tenantId}
   AND identity_type = #{identityType}
   AND external_key = #{externalKey}

SELECT 
  FROM oa_iam.identity
 WHERE tenant_id = #{tenantId}
   AND employee_id = #{employeeId}

SELECT 
  FROM oa_iam.identity
 WHERE tenant_id = #{tenantId}
   AND status <> 'DELETED'

   AND identity_type = #{identityType}


   AND status = #{status}


   AND (display_name ILIKE concat('%', #{q}, '%')
        OR external_key ILIKE concat('%', #{q}, '%'))


   AND seq > #{cursor}

 ORDER BY seq
 LIMIT #{limit}

mapper.update:
UPDATE oa_iam.identity
   SET status = #{status},
       version = version + 1,
       updated_at = #{updatedAt}
 WHERE tenant_id = #{tenantId}
   AND id = CAST(#{id} AS uuid)
   AND version = #{version}
   AND status <> 'DELETED'

