SELECT 
  FROM oa_iam.identity
 WHERE tenant_id = #{tenantId}
   AND identity_type = #{identityType}
   AND external_key IN

    #{key}

   AND status IN ('ACTIVE', 'CREATED')
 ORDER BY seq

SELECT 
  FROM oa_iam.identity
 WHERE tenant_id = #{tenantId}
   AND identity_type = 'USER'
   AND status IN ('ACTIVE', 'CREATED')


   AND org_path LIKE concat(#{orgPathPrefix}, '%')


   AND org_id = #{orgId}


 ORDER BY seq
 LIMIT #{limit}

SELECT r.id AS roleId, r.code AS roleCode, r.name AS roleName, g.id AS grantId, g.subject_type AS subjectType FROM oa_iam.grant_record g JOIN oa_iam.role r ON r.id = g.role_id WHERE g.tenant_id = #{tenantId} AND g.revoked_at IS NULL AND g.valid_from <= #{now} AND (g.valid_to IS NULL OR g.valid_to > #{now}) AND ( (g.subject_type = 'USER' AND g.subject_id = #{userId})
OR (g.subject_type = 'ORG_UNIT' AND g.subject_id = CAST(#{orgId} AS varchar))
) ORDER BY r.code
